/*
 * A210341  Triangle generated by T(n,k) = Fibonacci(n-k+2)^k.
 * https://oeis.org/A210341
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabl, easy
 * Formula:   a(n) is the row‑major flattening of the triangle
 *            T(n,k)=Fib(n‑k+2)^k
 * Range:     u8 n <= 30, u16 n <= 58, u32 n <= 109, u64 n <= 198,
 *            u128 n <= 390, big any n
 * Helpers:   fib
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include "../utils/fib.h"

seq_t a(idx_t n)
{
    /* Find the row r such that r(r+1)/2 <= n < (r+1)(r+2)/2
       (row r has r+1 elements) */
    idx_t low = 0;
    idx_t high = n;          /* any bound ≥ r will do */
    while (low <= high) {
        idx_t mid = low + (high - low) / 2;
        unsigned __int128 t = (unsigned __int128)mid * (mid + 1) / 2;
        if (t <= n)
            low = mid + 1;
        else
            high = mid - 1;
    }
    idx_t r = high;          /* last mid with t <= n */

    /* Position k within that row */
    unsigned __int128 prevCnt = (unsigned __int128)r * (r + 1) / 2;
    idx_t k = n - (idx_t)prevCnt;   /* 0 <= k <= r */

    /* Compute Fib(r - k + 2) */
    idx_t fibIdx = r - k + 2;
    seq_t fibVal = fib(fibIdx);

    /* Compute fibVal^k */
    seq_t result = 1;
    for (idx_t i = 0; i < k; ++i)
        result *= fibVal;

    return result;
}
